	opEQ         = "eq"
	opNEQ        = "neq"
	opLT         = "lt"
	opLTE        = "lte"
	opGT         = "gt"
	opGTE        = "gte"
	opEmpty      = "empty"
	opNotEmpty   = "notempty"
	opTrue       = "true"
	opFalse      = "false"
	opPresent    = "present"
	opNotPresent = "notpresent"
	opPrefix     = "prefix"
	opSuffix     = "suffix"
)

