		var cid, property, operator, value sql.NullString
		var typ sql.NullInt64
		if err := rows.Scan(&id, &segment, &cid, &typ, &property, &operator, &value); err != nil { rows.Close(); return resp, err }
		rule := byID[id]
		if rule == nil {
			rule = &evalRule{id: id, segmentKey: segment}
			byID[id] = rule
			rules = append(rules, rule)
		}
		if cid.Valid {
			rule.constraints = append(rule.constraints, evalConstraint{flipt.ComparisonType(typ.Int64), property.String, operator.String, value.String})
		}
	}
	if err := rows.Err(); err != nil { rows.Close(); return resp, err }
	if err := rows.Close(); err != nil { return resp, err }

	for _, rule := range rules {
		matched := true
		for _, c := range rule.constraints {
			ok, err := compareConstraint(c, r.Context)
			if err != nil { return resp, err }
			if !ok { matched = false; break }
		}
		if !matched { continue }
		resp.Match = true
		resp.SegmentKey = rule.segmentKey
		distributions, err := s.loadDistributions(ctx, rule.id)
		if err != nil { return resp, err }
		var cutoff int
		bucket := int(crc32.ChecksumIEEE([]byte(r.FlagKey+r.EntityId)) % evaluationBucketCount)
		for _, d := range distributions {
			if d.rollout <= 0 { continue }
			cutoff += int(d.rollout * 10)
			if bucket < cutoff { resp.Value = d.variantKey; return resp, nil }
		}
		return resp, nil
	}
	logger.Debug("no rules match")
	return resp, nil
}

func (s *EvaluatorStorage) loadDistributions(ctx context.Context, ruleID string) ([]evalDistribution, error) {
	rows, err := s.builder.Select("d.rollout, v.key").From("distributions d").
		Join("variants v ON (d.variant_id = v.id)").Where(sq.Eq{"d.rule_id": ruleID}).QueryContext(ctx)
	if err != nil { return nil, err }
	defer rows.Close()
	var out []evalDistribution
	for rows.Next() {
		var d evalDistribution
		if err := rows.Scan(&d.rollout, &d.variantKey); err != nil { return nil, err }
		out = append(out, d)
	}
	return out, rows.Err()
}

var noValueOperators = map[string]bool{"empty": true, "notempty": true, "present": true, "notpresent": true, "true": true, "false": true}

func compareConstraint(c evalConstraint, values map[string]string) (bool, error) {
	if strings.TrimSpace(c.property) == "" { return false, fmt.Errorf("empty property") }
	op := strings.ToLower(strings.TrimSpace(c.operator))
	value, present := values[c.property]
	if _, ok := noValueOperators[op]; !ok && c.value == "" { return false, fmt.Errorf("operator %q requires a value", op) }
	switch c.typeID {
	case flipt.ComparisonType_STRING_COMPARISON_TYPE:
		actual, expected := strings.TrimSpace(value), strings.TrimSpace(c.value)
		switch op {
		case "eq": return actual == expected, nil
		case "neq": return actual != expected, nil
		case "empty": return strings.TrimSpace(value) == "", nil
		case "notempty": return strings.TrimSpace(value) != "", nil
		case "present": return present, nil
		case "notpresent": return !present, nil
		case "prefix": return strings.HasPrefix(actual, expected), nil
		case "suffix": return strings.HasSuffix(actual, expected), nil
		}
	case flipt.ComparisonType_NUMBER_COMPARISON_TYPE:
		if op == "present" { return present, nil }; if op == "notpresent" { return !present, nil }
		actual, err := strconv.ParseFloat(strings.TrimSpace(value), 64); if err != nil { return false, fmt.Errorf("parsing number from %q", value) }
		expected, err := strconv.ParseFloat(strings.TrimSpace(c.value), 64); if err != nil { return false, fmt.Errorf("parsing number from %q", c.value) }
		switch op { case "eq": return actual == expected,nil; case "neq": return actual != expected,nil; case "lt": return actual < expected,nil; case "lte": return actual <= expected,nil; case "gt": return actual > expected,nil; case "gte": return actual >= expected,nil }
	case flipt.ComparisonType_BOOLEAN_COMPARISON_TYPE:
		if op == "present" { return present, nil }; if op == "notpresent" { return !present, nil }
		actual, err := strconv.ParseBool(strings.TrimSpace(value)); if err != nil { return false, fmt.Errorf("parsing boolean from %q", value) }
		switch op { case "true": return actual,nil; case "false": return !actual,nil }
	}
	return false, ErrInvalidf("unsupported operator %q for constraint type %s", op, c.typeID.String())
}
